def clean(df):
    df = df.copy()
    df['species'] = df['species'].str.strip()
    df['species'] = df['species'].replace({'adelie': 'Adelie', 'Adeile': 'Adelie', 'Gentto': 'Gentoo', 'Chinstarp': 'Chinstrap'})
    return df

def answer(df):
    adelie = df[df['species'] == 'Adelie']
    return adelie.groupby('island')['bill_length_mm'].mean().to_dict()
